    "description": "Part of the Scarlet &amp; Violet era, Gem Pack Vol. 5 continues China’s exclusive “Gem Pack” series, designed as a premium, compact alternative to standard expansions. Each booster box includes 18 packs, with 4 cards per pack.\nThe defining feature of this volume is its deep integration with Pokémon Horizons. The set highlights the Rising Volt Tacklers crew, pairing trainers with their evolving partner Pokémon in full-art illustration rares. Notable examples include Captain Pikachu with Friede, Floragato with Liko, Crocalor with Roy, and Quaxwell with Dot, each presented in cinematic, story-driven artwork. \nIn addition to these headline cards, the set includes multiple holo variations for each Pokémon, such as patterned foils, Master Ball-style finishes, and stamped designs, significantly expanding collectability within a relatively compact set. \nGem Pack Vol. 5 stands out for its blend of anime storytelling, premium card treatments, and regional exclusivity, making it a compelling addition for collectors.",
