    "name": "Scarlet & Violet - White Flare English Booster Pack",
    "description": "This set features Pokémon from the Unova Region featured in the Generation V Pokémon Black and White series. The set features a wide variety of Pokémon EX that have game changing abilities, attacks, and incredible new power! Nearly every Pokémon discovered in the Unova region has returned as a new illustration rare or special illustration rare card that showcases their unique charms.\nThis set is huge in scope, and features all 156 pokemon with a secret rare, art rare, or better, as well as introducing Tinsel Holofoil with the release of this set. For the collectors White Flare also introduceds a new rarity ofcards called \"Black White Rare\", which feature Pokémon against a solid black background with a monochromatic design and holofoil patterning. Will you be the one to pull a BWR Zekrom Ex or Reshiram EX?\nThis is perfect for both collectors and players alike. Wether you're looking for the super rare cards to add to your collection, or looking for powerful EX cards to add to your battle deck then this is a must-purchase item for any players keeping an eye on the latest sets.\n\n\nReunite with the Pokémon of Unova and rise to the top as a Trainer in a land of unity and legends! Evolve first partners Tepig and Oshawott all the way to Emboar and Samurott, and discover the undeniable power of truth with the region’s Legendary and Mythical Pokémon, including Reshiram ex and Keldeo ex. As you fill out your Pokédex, keep an eye out for special illustrations of each Pokémon and parallel cards with Poké Ball patterns in the Pokémon TCG: Scarlet &amp; Violet—White Flare expansion!",
